def trial_balance(ledger, as_of=None):
    _check_ledger(ledger)
    _check_as_of(as_of)
    sums = {}
    for tx, p in ledger.postings():
        if as_of is not None and tx.date > as_of:
            continue
        _add(sums, (p.account, p.amount.currency), p.amount.minor)
    accounts = []
    totals = {}
    for account, cur, v in _account_lines(sums):
        t = totals.setdefault(cur, [0, 0])
        if v > 0:
            t[0] += v
        else:
            t[1] += -v
        accounts.append({"account": account, "type": _type_of(account),
                         "debit": _m(v, cur) if v > 0 else None,
                         "credit": _m(-v, cur) if v < 0 else None})
    return {"report": "trial_balance", "as_of": _date_text(as_of), "accounts": accounts,
            "totals": [{"currency": c, "debit": _m(d, c), "credit": _m(cr, c), "balanced": d == cr}
                       for c, (d, cr) in sorted(totals.items())]}


# ------------------------------------------------------------ balance sheet
def balance_sheet(ledger, as_of=None, convert_to=None, today=None):
    _check_ledger(ledger)
    _check_as_of(as_of)
    if convert_to is not None and as_of is None:
        raise ReportError("converting needs a date: give as_of with convert_to")
    _check_convert_to(convert_to)
    sections = {"asset": {}, "liability": {}, "equity": {}}
    retained = {}
    for tx, p in ledger.postings():
        if as_of is not None and tx.date > as_of:
            continue
        t = _type_of(p.account)
        cur, v = p.amount.currency, p.amount.minor
        if t == "asset":
            _add(sections["asset"], (p.account, cur), v)
        elif t in ("liability", "equity"):
def register(ledger, account, period=None, rollup=False):
    _check_ledger(ledger)
    _check_period(period, optional=True)
    if not isinstance(rollup, bool):
        raise ReportError("rollup must be true or false, got %r" % (rollup,))
    if not isinstance(account, str) or not ledger.chart.exists(account):
        raise ReportError("no such account %s" % ("'%s'" % account if isinstance(account, str) else repr(account)))
    prefix = account + ":"
    opening, running, rows = {}, {}, []
    for tx in ledger.transactions():
        if period is not None and tx.date > period.end:
            continue
        for p in tx.postings:
            if not (p.account == account or (rollup and p.account.startswith(prefix))):
                continue
            cur, v = p.amount.currency, p.amount.minor
            opening.setdefault(cur, 0)
            running.setdefault(cur, 0)
            running[cur] += v
            if period is not None and tx.date < period.start:
                opening[cur] += v
                continue
            rows.append({"date": _date_text(tx.date), "id": tx.id, "payee": tx.payee, "narration": tx.narration,
                         "account": p.account, "amount": _m(v, cur), "balance": _m(running[cur], cur)})
    return {"report": "register", "account": account, "rollup": rollup,
            "start": _date_text(period.start) if period is not None else None,
            "end": _date_text(period.end) if period is not None else None,
            "opening": _money_list(opening, True), "rows": rows, "closing": _money_list(running, True)}


def render_text(report):
    kind = _kind(report)
    try:
        title, headers, rows, align = _TEXT[kind](report)
    except (KeyError, TypeError, IndexError, AttributeError):
        raise ReportError("malformed %s report" % kind) from None
    return title + "\n\n" + render_table(headers, rows, align)


# --------------------------------------------------------------------- CSV
def _csv_trial_balance(r):
    rows = []
    for a in r["accounts"]:
        m = a["debit"] or a["credit"]

    @classmethod
    def parse(cls, text):
        if not isinstance(text, str):
            raise DateError("invalid period %r" % (text,))
        try:
            m = re.fullmatch(r"([0-9]{4})", text)
            if m:
                y = int(m.group(1))
                return cls(datetime.date(y, 1, 1), datetime.date(y, 12, 31))
            m = re.fullmatch(r"([0-9]{4})-([0-9]{2})", text)
            if m:
                y, mo = int(m.group(1)), int(m.group(2))
                return cls(datetime.date(y, mo, 1), datetime.date(y, mo, last_day(y, mo)))
            m = re.fullmatch(r"([0-9]{4})-Q([1-4])", text)
            if m:
                y, q = int(m.group(1)), int(m.group(2))
                mo = _QUARTER_START[q]
                return cls(datetime.date(y, mo, 1), datetime.date(y, mo + 2, last_day(y, mo + 2)))
            m = re.fullmatch(r"([0-9]{4}-[0-9]{2}-[0-9]{2})\.\.([0-9]{4}-[0-9]{2}-[0-9]{2})", text)
            if m:
                return cls(parse_date(m.group(1)), parse_date(m.group(2)))
        except (ValueError, DateError):
            pass
        raise DateError("invalid period '%s': expected YYYY, YYYY-MM, YYYY-QN or YYYY-MM-DD..YYYY-MM-DD" % text)


def _period_of(d, step):
    if step == "week":
        start = d - datetime.timedelta(days=d.weekday())
        try:
            end = start + datetime.timedelta(days=6)
        except OverflowError:
            end = datetime.date.max
        return Period(start, end)
    if step == "month":
        return Period(d.replace(day=1), d.replace(day=last_day(d.year, d.month)))
    if step == "quarter":
        mo = (d.month - 1) // 3 * 3 + 1
        return Period(datetime.date(d.year, mo, 1), datetime.date(d.year, mo + 2, last_day(d.year, mo + 2)))
    return Period(datetime.date(d.year, 1, 1), datetime.date(d.year, 12, 31))



    @classmethod
    def of(cls, text, code):
        return cls(parse_amount(text, code), code)

    @classmethod
    def parse(cls, text):
        if not isinstance(text, str):
            raise MoneyError("invalid money %r: expected text" % (text,))
        parts = text.split(" ")
        if len(parts) != 2 or not parts[0] or not parts[1] or any(c in text for c in "\t\r\n\v\f"):
            raise MoneyError("invalid money '%s': expected 'AMOUNT CUR'" % (text,))
        amount, code = parts
        currency(code)
        return cls(parse_amount(amount, code), code)

    def amount_str(self):
        return r if r is NotImplemented else not r

    def __hash__(self):
        return hash(self._key())

    def __repr__(self):
        return "BudgetLine(%s)" % ", ".join("%s=%r" % (f, getattr(self, f)) for f in self._FIELDS)

    def to_dict(self):
        def money(m):
            return {"amount": m.amount_str(), "currency": m.currency}
        return {
            "pattern": self._pattern,
            "period_kind": self._period_kind,
            "budget": money(self._budget),
            "actual": money(self._actual),
            "remaining": money(self._remaining),
            "percent": str(self._percent),
            "over": bool(self._over),
            "accounts": [{"account": a, "amount": money(m)} for a, m in self._accounts],
        }


"""Error hierarchy shared by every tallybook module."""


class TallybookError(Exception):
    """Base class of every error caused by what was asked for."""

    code = "error"

    def __init__(self, message="", **detail):
        super().__init__(message)
        self.message = str(message)
        self.detail = dict(detail) if detail else {}

    def __str__(self):
        return self.message


class ParseError(TallybookError):
    code = "parse"

